public class JArrayBasic2
{
   public static void main (String[] args)
   {
	  //#Step 1: Define an array of five floating-point numbers
	   double[] lst = {1.9, 2.9, 3.4, 3.5, 3.9};
	   //Step 2: Update the array element
	   lst[1] = 20.5;
	   //Step 3: Print the array elements
	   for (double x : lst) {
		   System.out.print(x + "  ");
	   }
   }
}
